mapper.select:
SELECT o.id AS orderId, o.order_no AS orderNo, si.title AS showTitle, ss.session_time AS sessionTime, o.pay_amount AS payAmount, o.status AS status, o.expire_time AS expireTime, o.create_time AS createTime FROM orders o LEFT JOIN show_info si ON si.id = o.show_id LEFT JOIN show_session ss ON ss.id = o.session_id WHERE o.user_id = #{userId}
AND o.status = #{status}
AND o.id < #{cursor}
ORDER BY o.id DESC LIMIT #{limit}

SELECT o.id AS orderId, o.order_no AS orderNo, si.title AS showTitle, u.nickname AS buyerNickname, RIGHT(u.phone, 4) AS buyerPhone, (SELECT COUNT(*) FROM order_item oi WHERE oi.order_id = o.id) AS quantity, o.pay_amount AS payAmount, o.status AS status, o.create_time AS createTime FROM orders o LEFT JOIN show_info si ON si.id = o.show_id LEFT JOIN `user` u ON u.id = o.user_id WHERE o.merchant_id = #{merchantId}
AND o.status = #{q.status}
AND o.show_id = #{q.showId}
AND o.order_no = #{q.orderNo}
ORDER BY o.id DESC

SELECT o.id AS orderId, o.order_no AS orderNo, o.user_id AS userId, u.phone AS phone, u.nickname AS nickname, o.vip_plan_code AS vipPlanCode, o.pay_amount AS amount, o.status AS status, o.create_time AS createTime, o.pay_time AS payTime FROM orders o LEFT JOIN `user` u ON u.id = o.user_id WHERE o.order_type = 2
AND o.status = #{q.status}
AND o.vip_plan_code = #{q.planCode}
AND u.phone = #{q.phone}
ORDER BY o.id DESC
